let faSortUI={key:'ovr',direction:-1};
const FA_SORT_OPTIONS=[['ovr','Overall'],['pot','Potential'],['age','Age'],['contract','Contract (offer total)'],['demand','Salary demand'],['interest','Interest']];
function setFASort(key,value){if(key==='key'&&FA_SORT_OPTIONS.some(([k])=>k===value))faSortUI.key=value;else if(key==='direction'&&[1,-1].includes(Number(value)))faSortUI.direction=Number(value);else return;render()}
function faMarketRows(players){return players.map(p=>{const active=faActive(),e=active?faEntry(p.id):null,o=active?state.freeAgency.offers.find(o=>o.id===p.id&&o.team===controlledTeamId()):null,demand=e?.demand??freeAgentQuote(p),estimate=e?faInterest(p,team(),o||{salary:demand,minutes:24}):null;return {p,o,e,ovr:p.ovr,pot:p.pot,age:p.age,contract:o?o.salary*o.years:null,demand,interest:estimate?Math.max(0,Math.min(100,estimate.score)):null,feedback:estimate?.feedback}}).sort((a,b)=>{const x=a[faSortUI.key],y=b[faSortUI.key];return x===null?(y===null?a.p.id-b.p.id:1):y===null?-1:(x-y)*faSortUI.direction||a.p.id-b.p.id})}
function faMarketTable(players){const rows=faMarketRows(players);return `<section class="panel"><div class="panelhead"><h2>Available players</h2><span>${rows.length} players</span></div><div class="directory-filters"><label>Sort by<select onchange="setFASort('key',this.value)">${FA_SORT_OPTIONS.map(([k,n])=>`<option value="${k}" ${faSortUI.key===k?'selected':''}>${n}</option>`).join('')}</select></label><label>Order<select onchange="setFASort('direction',this.value)"><option value="-1" ${faSortUI.direction===-1?'selected':''}>Highest first</option><option value="1" ${faSortUI.direction===1?'selected':''}>Lowest first</option></select></label></div><p class="note">Contract = total value of your submitted offer. Interest uses your offer, or an estimate at asking salary and 24 minutes per game. Interest is available during offseason bidding; missing values sort last.</p><div class="scroll" tabindex="0" role="region" aria-label="Free-agent market"><table><thead><tr><th>Player</th><th>POS</th><th>Age</th><th>OVR</th><th>POT</th><th>Status</th><th>Contract</th><th>Salary demand</th><th>Interest</th><th>Actions</th></tr></thead><tbody>${rows.map(r=>{const {p,o,e}=r,pending=faActive()&&state.freeAgency.pending.some(s=>s.id===p.id);return `<tr><th><button class="namebutton" onclick="profile(${p.id})">${escapeHTML(p.name)}</button>${p.international?`<small>${escapeHTML(INTERNATIONAL_COUNTRIES[p.international.country].name)} · ${INTERNATIONAL_PATHWAYS[p.international.pathway]}</small>`:''}</th><td>${p.pos}</td><td>${p.age}</td><td>${ratingMarkup(p.ovr)}</td><td>${ratingMarkup(p.pot)}</td><td>${e?.rfa?'RFA':'UFA'}${e?.former===controlledTeamId()?' · Your rights':''}</td><td>${o?money(r.contract)+' total · '+o.years+' yr · '+money(o.salary)+'/yr':'No offer'}</td><td>${money(r.demand)} / yr</td><td>${r.interest===null?'—':Math.round(r.interest)+' / 100'+(o?'':' · Estimate')+'<br><small>'+escapeHTML(r.feedback)+'</small>'}</td><td>${pending?'Offer sheet pending':`<button onclick="negotiateFreeAgent(${p.id})">${o?'Edit offer':'Negotiate'}</button>${o?` <button onclick="withdrawFreeAgentOffer(${p.id})">Withdraw</button>`:''}`}</td></tr>`}).join('')||'<tr><td colspan="10">No available players.</td></tr>'}</tbody></table></div></section>`}
